"use client";

import type { DocumentSummary } from "@/lib/types";

type DocumentLibraryProps = {
  documents: DocumentSummary[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onUpload: (file: File) => Promise<void>;
  uploading: boolean;
};

function formatDate(value: string) {
  return new Date(value).toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function prettyType(value: string) {
  return value.replaceAll("_", " ");
}

export function DocumentLibrary({
  documents,
  selectedId,
  onSelect,
  onUpload,
  uploading,
}: DocumentLibraryProps) {
  return (
    <section className="animate-rise stagger-2 flex h-full min-h-0 flex-col">
      <div className="mb-4 flex items-end justify-between gap-3">
        <div>
          <h2 className="font-display text-2xl text-ink">Document library</h2>
          <p className="mt-1 text-sm text-muted">
            Upload PDFs and inspect extracted page text.
          </p>
        </div>
        <label
          className={`cursor-pointer border border-accent bg-accent px-4 py-2 text-sm font-medium text-white transition hover:bg-accent-deep ${
            uploading ? "uploading-pulse pointer-events-none opacity-70" : ""
          }`}
        >
          {uploading ? "Uploading…" : "Upload PDF"}
          <input
            type="file"
            accept="application/pdf,.pdf"
            className="hidden"
            disabled={uploading}
            onChange={async (event) => {
              const file = event.target.files?.[0];
              event.target.value = "";
              if (file) await onUpload(file);
            }}
          />
        </label>
      </div>

      <ul className="min-h-0 flex-1 space-y-1 overflow-y-auto border-y border-line/80 py-2">
        {documents.length === 0 ? (
          <li className="px-1 py-8 text-sm text-muted">
            No documents yet. Upload a PDF or reseeds the demo set.
          </li>
        ) : (
          documents.map((doc) => {
            const active = doc.id === selectedId;
            return (
              <li key={doc.id}>
                <button
                  type="button"
                  onClick={() => onSelect(doc.id)}
                  className={`w-full border-l-2 px-3 py-3 text-left transition ${
                    active
                      ? "border-accent bg-white/70"
                      : "border-transparent hover:border-line hover:bg-white/40"
                  }`}
                >
                  <div className="truncate text-sm font-medium text-ink">
                    {doc.source_label || doc.original_filename}
                  </div>
                  <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted">
                    <span className="capitalize">{prettyType(doc.document_type)}</span>
                    <span>
                      {doc.page_count} page{doc.page_count === 1 ? "" : "s"}
                    </span>
                    <span>{formatDate(doc.uploaded_at)}</span>
                  </div>
                </button>
              </li>
            );
          })
        )}
      </ul>
    </section>
  );
}

"use client";

import { documentFileUrl } from "@/lib/api";
import type { DocumentDetail } from "@/lib/types";

type DocumentViewerProps = {
  patientId: string;
  document: DocumentDetail | null;
  loading: boolean;
};

export function DocumentViewer({
  patientId,
  document,
  loading,
}: DocumentViewerProps) {
  if (loading) {
    return (
      <section className="animate-fade flex h-full items-center justify-center text-sm text-muted">
        Loading document…
      </section>
    );
  }

  if (!document) {
    return (
      <section className="animate-fade flex h-full items-center justify-center px-6 text-center text-sm text-muted">
        Select a document to preview the PDF and extracted text.
      </section>
    );
  }

  return (
    <section className="animate-rise stagger-3 flex h-full min-h-0 flex-col gap-4">
      <header>
        <h2 className="font-display text-2xl text-ink">
          {document.source_label || document.original_filename}
        </h2>
        <p className="mt-1 text-sm text-muted">
          {document.original_filename} · {document.page_count} page
          {document.page_count === 1 ? "" : "s"} · extracted with page
          boundaries preserved
        </p>
      </header>

      <div className="grid min-h-0 flex-1 gap-4 lg:grid-cols-2">
        <div className="flex min-h-[320px] flex-col border border-line bg-white/60">
          <div className="border-b border-line px-3 py-2 text-xs uppercase tracking-[0.14em] text-muted">
            PDF preview
          </div>
          <iframe
            title={`PDF preview ${document.original_filename}`}
            src={documentFileUrl(patientId, document.id)}
            className="min-h-0 flex-1 w-full bg-white"
          />
        </div>

        <div className="flex min-h-[320px] flex-col border border-line bg-white/60">
          <div className="border-b border-line px-3 py-2 text-xs uppercase tracking-[0.14em] text-muted">
            Extracted text
          </div>
          <div className="min-h-0 flex-1 space-y-4 overflow-y-auto p-3">
            {document.pages.map((page) => (
              <article key={page.page_number}>
                <h3 className="mb-2 text-xs font-semibold uppercase tracking-[0.14em] text-accent-deep">
                  Page {page.page_number}
                </h3>
                <pre className="whitespace-pre-wrap font-sans text-sm leading-6 text-ink-soft">
                  {page.text || "(No extractable text on this page)"}
                </pre>
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useState, useTransition } from "react";
import {
  getDocument,
  getPatient,
  listDocuments,
  reseedDemo,
  uploadDocument,
} from "@/lib/api";
import type { DocumentDetail, DocumentSummary, Patient } from "@/lib/types";
import { DocumentLibrary } from "./DocumentLibrary";
import { DocumentViewer } from "./DocumentViewer";
import { PlaceholderPanel } from "./PlaceholderPanel";

const DEFAULT_PATIENT_ID = "patient-raymond-yao";

export function Dashboard() {
  const [patient, setPatient] = useState<Patient | null>(null);
  const [documents, setDocuments] = useState<DocumentSummary[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedDoc, setSelectedDoc] = useState<DocumentDetail | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [bootLoading, setBootLoading] = useState(true);
  const [docLoading, setDocLoading] = useState(false);
  const [, startTransition] = useTransition();

  async function refreshLibrary(selectId?: string | null) {
    const [nextPatient, nextDocs] = await Promise.all([
      getPatient(DEFAULT_PATIENT_ID),
      listDocuments(DEFAULT_PATIENT_ID),
    ]);
    setPatient(nextPatient);
    setDocuments(nextDocs);
    const nextSelected =
      selectId === undefined
        ? nextDocs[0]?.id ?? null
        : selectId && nextDocs.some((d) => d.id === selectId)
          ? selectId
          : nextDocs[0]?.id ?? null;
    setSelectedId(nextSelected);
  }

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        setBootLoading(true);
        setError(null);
        await refreshLibrary();
      } catch (err) {
        if (!cancelled) {
          setError(
            err instanceof Error
              ? err.message
              : "Could not reach the Unburden API. Is it running on :8000?",
          );
        }
      } finally {
        if (!cancelled) setBootLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!selectedId) {
      setSelectedDoc(null);
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        setDocLoading(true);
        const detail = await getDocument(DEFAULT_PATIENT_ID, selectedId);
        if (!cancelled) setSelectedDoc(detail);
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Failed to load document");
        }
      } finally {
        if (!cancelled) setDocLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [selectedId]);

  async function handleUpload(file: File) {
    try {
      setUploading(true);
      setError(null);
      const created = await uploadDocument(DEFAULT_PATIENT_ID, file);
      await refreshLibrary(created.id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Upload failed");
    } finally {
      setUploading(false);
    }
  }

  async function handleReseed() {
    try {
      setError(null);
      setBootLoading(true);
      await reseedDemo();
      await refreshLibrary();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Reseed failed");
    } finally {
      setBootLoading(false);
    }
  }

  return (
    <div className="relative z-10 mx-auto flex min-h-screen w-full max-w-7xl flex-col px-5 py-8 sm:px-8">
      <header className="animate-rise mb-8">
        <p className="text-xs uppercase tracking-[0.22em] text-muted">
          Prior authorization evidence engine
        </p>
        <div className="mt-2 flex flex-wrap items-end justify-between gap-4">
          <div>
            <h1 className="font-display text-5xl tracking-tight text-ink sm:text-6xl">
              Unburden
            </h1>
            <p className="mt-3 max-w-xl text-base leading-7 text-ink-soft">
              Review source documents, verify extracted evidence, and assemble a
              compact packet for insurance review.
            </p>
          </div>
          <button
            type="button"
            onClick={() => startTransition(() => void handleReseed())}
            className="border border-line bg-white/50 px-4 py-2 text-sm text-ink-soft transition hover:border-ink/30 hover:bg-white"
          >
            Reload demo documents
          </button>
        </div>
      </header>

      {patient && (
        <div className="animate-rise stagger-1 mb-6 border-y border-line/80 py-4">
          <p className="text-xs uppercase tracking-[0.16em] text-muted">Patient</p>
          <p className="mt-1 font-display text-2xl text-ink">{patient.display_name}</p>
          <p className="text-sm text-muted">
            DOB {patient.date_of_birth ?? "—"} · id {patient.id}
          </p>
        </div>
      )}

      {error && (
        <div className="mb-6 border border-warning/40 bg-[#fff8ef] px-4 py-3 text-sm text-warning">
          {error}
        </div>
      )}

      {bootLoading ? (
        <p className="animate-fade text-sm text-muted">Loading workspace…</p>
      ) : (
        <>
          <div className="grid min-h-[520px] gap-8 lg:grid-cols-[minmax(260px,320px)_minmax(0,1fr)]">
            <DocumentLibrary
              documents={documents}
              selectedId={selectedId}
              onSelect={setSelectedId}
              onUpload={handleUpload}
              uploading={uploading}
            />
            <DocumentViewer
              patientId={DEFAULT_PATIENT_ID}
              document={selectedDoc}
              loading={docLoading}
            />
          </div>

          <div className="mt-10 grid gap-8 md:grid-cols-3">
            <PlaceholderPanel
              title="Clinical observations"
              milestone="Milestone 2"
              description="Structured findings with source citations will appear here after extraction lands."
            />
            <PlaceholderPanel
              title="Insurance requirements"
